import {money,date,asDate,iso,eventDetail} from './format.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=v=>String(v||'Unknown').replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const statuses=['NOT_CONTACTED','CONTACTED','WAITING','INTERESTED','TERMS_RECEIVED','DECLINED','CLOSED','WITHDRAWN'];
const declines=['DEAL_TOO_SMALL','DEAL_TOO_LARGE','WRONG_SECTOR','LEVERAGE_TOO_HIGH','RETURN_TOO_LOW','SECURITY_UNSUITABLE','TERM_UNSUITABLE','NO_CAPITAL_AVAILABLE','TIMING','OTHER'];
const stages=['draft','adviser_review','ready_to_send','sent_to_lender','more_information_needed','terms_review','due_diligence','documentation','funded','closed','withdrawn','archived'];
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',deals:'M3 6h7l2 2h9v12H3z M3 6V4h6l2 2',providers:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a5 5 0 0 1 5-5h6a5 5 0 0 1 5 5v3',followups:'M5 5h14v16H5z M8 3v4 M16 3v4 M5 10h14 M8 14h3 M8 17h7',activity:'M12 3a9 9 0 1 0 9 9 M12 7v5l4 3 M16 3h5v5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.deals}"/></svg>`;
const badge=(v,tone='')=>`<span class="badge ${esc(tone)}">${esc(label(v))}</span>`;
const opt=(values,selected,placeholder)=>`${placeholder?`<option value="">${esc(placeholder)}</option>`:''}${values.map(v=>{const value=typeof v==='object'?v.id:v,name=typeof v==='object'?v.name:label(v);return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(name)}</option>`;}).join('')}`;
const input=(name,title,value='',type='text',extra='')=>`<label>${esc(title)}<input name="${esc(name)}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const select=(name,title,values,value,placeholder)=>`<label>${esc(title)}<select name="${name}">${opt(values,value,placeholder)}</select></label>`;
const textarea=(name,title,value='')=>`<label class="wide">${esc(title)}<textarea name="${name}">${esc(value)}</textarea></label>`;
const errorSlot='<p class="error" role="alert"></p>';
const empty=s=>`<p class="empty">${esc(s)}</p>`;
let appData=null,detail=null,config=null,routeSerial=0,noticeTimer;
try{if(localStorage.getItem('mandate-workspace-theme')==='dark')document.body.classList.add('dark');}catch{}
function notify(message){$('#notice').textContent=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').textContent='',4500);}
async function api(path,body){const r=await fetch('/api'+path,{credentials:'same-origin',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)})});let v;try{v=await r.json();}catch{throw new Error('The server did not respond correctly. Check the connection and retry.');}if(!r.ok){if(r.status===401&&path!=='/login')await loginView();throw new Error(v.error||'Request failed.');}return v;}
const dealLink=(id,tab='summary')=>`#deal/${encodeURIComponent(id)}/${tab}`;
const providerName=id=>appData.providers.find(p=>p.id===id)?.name||id;
const userName=id=>appData.users.find(u=>u.id===id)?.name||'Broker';
function recentRun(saved=false){return detail.matching_runs.filter(r=>!saved||r.saved_at).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0];}
function formButtons(text='Save changes'){return `<div class="form-actions"><button class="primary" type="submit">${text}</button>${errorSlot}</div>`;}
function shell(){const page=location.hash.slice(1).split('/')[0]||'overview';$('#app').innerHTML=`<aside class="rail"><a class="wordmark" href="#overview">Mandate<span>.</span></a><div class="firm"><strong>${esc(appData.organisation?.name||'Your brokerage')}</strong><span class="muted">Adviser workspace</span></div><nav aria-label="Main navigation">${[['overview','Overview'],['deals','Deals'],['providers','Capital providers'],['followups','Follow-ups'],['activity','Activity']].map(([id,name])=>`<a href="#${id}" class="navlink ${page===id||page==='deal'&&id==='deals'?'active':''}">${icon(id)}${name}</a>`).join('')}</nav><div class="rail-foot"><span>${esc(appData.user.name)}</span><a href="/prototype/index.html">Original product demo</a><button class="small" data-action="logout">Sign out</button></div></aside><div class="shell"><header class="topbar"><span class="synthetic">${config.synthetic?'Fictional data · saved on this server':'Private brokerage workspace'}</span><div class="actions"><button class="small quiet" data-action="theme">${document.body.classList.contains('dark')?'Light':'Dark'} mode</button><button class="small" data-action="logout">Sign out</button></div></header><main id="content" tabindex="-1"><div class="loading" role="status">Loading…</div></main></div>`;}
async function loginView(){config=await api('/auth/config');appData=null;$('#app').innerHTML=`<main class="login"><a class="wordmark" href="/prototype/index.html">Mandate<span>.</span></a><h1>Your deal workspace</h1><p>${config.synthetic?'Use a fictional broker account to explore saved deals, lender relationships and funding packages.':'Sign in to your private brokerage workspace.'}</p><form data-form="login">${config.mode==='demo'?select('user_id','Fictional broker',config.accounts,config.accounts[0]?.id):input('email','Email','','email','required')+input('password','Password','','password','required')}<button class="primary">Open workspace</button>${errorSlot}</form><footer>${config.synthetic?'Local demonstration only. Keep real borrower records out of this environment.':'Your brokerage membership controls access to deals.'}</footer></main>`;}
async function route(){const serial=++routeSerial;try{if(!config)config=await api('/auth/config');appData=await api('/bootstrap');if(serial!==routeSerial)return;shell();const parts=location.hash.slice(1).split('/'),page=parts[0]||'overview',rid=decodeURIComponent(parts[1]||'');
 if(page==='deal'){detail=await api('/deals/'+encodeURIComponent(rid));if(serial!==routeSerial)return;$('#content').innerHTML=dealView(parts[2]||'summary');}
 else if(page==='new')$('#content').innerHTML=newDealView();
 else if(page==='provider'){const p=appData.providers.find(p=>p.id===rid);if(!p)throw new Error('Provider not found.');const exclude=parts[2]?`?exclude_deal_id=${encodeURIComponent(parts[2])}`:'';const h=await api('/providers/'+encodeURIComponent(rid)+'/history'+exclude);$('#content').innerHTML=providerView(p,h);}
 else if(page==='report'){const report=await api('/reports/'+encodeURIComponent(rid));$('#content').innerHTML=reportView(report);}
 else $('#content').innerHTML=page==='deals'?dealsView():page==='providers'?providersView():page==='followups'?followupsView():page==='activity'?`<div class="page-head"><div><h1>Activity</h1><p>Recorded actions across your brokerage.</p></div></div><section class="panel">${timeline(appData.deal_events)}</section>`:overviewView();
 }catch(e){if(appData&&$('#content'))$('#content').innerHTML=`<h1>Unable to open this page</h1><p class="error">${esc(e.message)}</p><button data-action="reload">Try again</button>`;}}
function head(title,subtitle,action=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function overdue(m){return m.next_follow_up_at&&new Date(m.next_follow_up_at)<new Date();}
function followupsView(){const ms=appData.deal_matches.filter(m=>m.next_follow_up_at).sort((a,b)=>new Date(a.next_follow_up_at)-new Date(b.next_follow_up_at));return head('Follow-ups','Every due date has a deal, a provider and an owner.')+`<section class="panel">${ms.length?ms.map(m=>followItem(m)).join(''):empty('No follow-ups scheduled. Set the next action from a deal’s provider table.')}</section>`;}
function followItem(m){const d=appData.deals.find(d=>d.id===m.deal_id);return `<div class="next-item"><div class="actions">${badge(overdue(m)?'Overdue':'Upcoming',overdue(m)?'warn':'')}<small>${date(m.next_follow_up_at)}</small></div><p><a href="${dealLink(m.deal_id,'matches')}">${esc(providerName(m.provider_id))}</a></p><p>${esc(d?.deal_name)} · ${esc(userName(m.assigned_user_id))}</p>${m.follow_up_note?`<p>${esc(m.follow_up_note)}</p>`:''}</div>`;}
function overviewView(){const active=appData.deals.filter(d=>!['closed','withdrawn','archived'].includes(d.overall_stage)),due=appData.deal_matches.filter(m=>m.next_follow_up_at).sort((a,b)=>new Date(a.next_follow_up_at)-new Date(b.next_follow_up_at));return head('Your workspace','A clear view of what needs to move next.',`<a class="btn primary" href="#new">New deal</a>`)+`<div class="ledger"><div><small>Active deals</small><strong>${active.length}</strong></div><div><small>Requested debt · active deals</small><strong>${money(active.reduce((n,d)=>n+(d.profile.funding.amount||0),0))}</strong></div><div><small>Overdue follow-ups</small><strong>${due.filter(overdue).length}</strong></div><div><small>Profiles awaiting confirmation</small><strong>${active.filter(d=>d.profile_version!==d.confirmed_version).length}</strong></div></div><div class="split"><div><section class="panel"><div class="panel-head"><h2>Active transactions</h2><a href="#deals">View all deals</a></div>${dealTable(active)}</section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><a href="#activity">View history</a></div>${timeline(appData.deal_events.slice(0,5))}</section></div><aside><section class="panel"><div class="panel-head"><h2>Next actions</h2><a href="#followups">All</a></div>${appData.deal_matches.some(m=>m.status==='TERMS_RECEIVED')?`<p><a href="#deals">${appData.deal_matches.filter(m=>m.status==='TERMS_RECEIVED').length} providers have terms to review</a></p>`:''}${due.length?due.slice(0,4).map(followItem).join(''):empty('No follow-ups due.')}</section><section class="panel"><h2>Prepare for approach</h2><p class="muted">Confirm source details, review lender fit, then record the next conversation.</p>${appData.deals.some(d=>d.id==='DEAL-30M')?`<a href="${dealLink('DEAL-30M')}">Explore the NZ$30m example</a>`:'<a href="#new">Prepare a new draft</a>'}</section></aside></div>`;}
function dealTable(deals,extended=false){return deals.length?`<div class="table-scroll"><table><thead><tr><th>Deal / borrower</th><th>Requested</th><th>Stage</th><th>Providers</th>${extended?'<th>Contacted / interested / declined / terms</th><th>Created / last action / follow-up</th>':''}<th>Broker</th></tr></thead><tbody>${deals.map(d=>{const ms=appData.deal_matches.filter(m=>m.deal_id===d.id),contacted=new Set(appData.deal_events.filter(e=>e.deal_id===d.id&&(e.new_status==='CONTACTED'||e.event_type==='PROVIDER_CONTACTED')).map(e=>e.deal_match_id)).size;return `<tr><td><a href="${dealLink(d.id)}">${esc(d.deal_name)}</a><small>${esc(d.profile.company.name||d.profile.company.alias||'Borrower to confirm')}</small><small>${esc(d.profile.company.industry||'Industry not supplied')}</small></td><td class="num">${money(d.profile.funding.amount)}</td><td>${badge(d.overall_stage)}</td><td>${ms.length}</td>${extended?`<td class="num">${contacted} / ${ms.filter(m=>m.status==='INTERESTED').length} / ${ms.filter(m=>m.status==='DECLINED').length} / ${ms.filter(m=>m.status==='TERMS_RECEIVED').length}</td><td>${date(d.created_at)}<small>Updated ${date(d.updated_at)}</small><small>Follow-up ${date(ms.filter(m=>m.next_follow_up_at).sort((a,b)=>new Date(a.next_follow_up_at)-new Date(b.next_follow_up_at))[0]?.next_follow_up_at)}</small></td>`:''}<td>${esc(userName(d.assigned_user_id))}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No deals found. Create a draft to get started.');}
function dealsView(){return head('Deals','Find the transaction, owner or next step you need.',`<a class="btn primary" href="#new">New deal</a>`)+`<form class="filters" data-form="filter-deals">${input('search','Search deals','','search')}${select('stage','Stage',stages,'','All stages')}${select('broker','Broker',appData.users,'','All brokers')}${select('industry','Industry',[...new Set(appData.deals.map(d=>d.profile.company.industry).filter(Boolean))],'','All industries')}${select('due','Follow-up',[{id:'all',name:'All dates'},{id:'overdue',name:'Overdue only'}],'all')}${select('sort','Sort by',[{id:'updated',name:'Recently updated'},{id:'amount',name:'Largest amount'},{id:'created',name:'Newest first'}],'updated')}<button>Apply</button></form><p class="muted">Contacted counts recorded contact history; other provider counts show current status.</p><section class="panel" id="deal-table">${dealTable(appData.deals,true)}</section>`;}
function timeline(events){return events.length?`<ol class="timeline">${events.map(e=>{const name=e.provider_id?providerName(e.provider_id):appData.deals.find(d=>d.id===e.deal_id)?.deal_name;const action=e.new_status?`marked ${label(e.new_status)}`:label(e.event_type);const metadata=e.metadata||{};const extra=eventDetail(e);return `<li><small>${date(e.occurred_at||e.created_at,true)}</small><div><p><strong>${esc(name||'Deal')}</strong> ${esc(action)}</p><small>${esc(userName(e.actor_user_id))}</small>${extra?`<p class="metadata">${esc(extra)}</p>`:''}</div></li>`;}).join('')}</ol>`:empty('No recorded activity yet.');}
function profileFields(p){return `${input('company_name','Borrower / company',p.company.name)}${input('industry','Industry',p.company.industry)}${input('location','Location',p.company.location)}${input('country','Country',p.company.country||'New Zealand')}${input('amount','Funding requested (NZD)',p.funding.amount,'number','min="0" step="0.01"')}${input('purpose','Funding purpose',p.funding.purpose)}${input('purposes','Purpose categories, separated by commas',(p.funding.purposes||[]).join(', '))}${input('term','Term (months)',p.funding.termMonths,'number','min="1" max="600"')}${input('security','Security, separated by commas',(p.funding.security||[]).join(', '))}${input('revenue','Annual revenue (NZD)',p.financials.annualRevenue.amount,'number','min="0" step="0.01"')}${input('ebitda','EBITDA (NZD)',p.financials.ebitda.amount,'number','step="0.01"')}${input('period','Financial period end',p.financials.ebitda.periodEnd,'date')}${input('existingDebt','Existing gross debt (NZD)',p.ratios?.existingDebt,'number','min="0" step="0.01"')}${input('cash','Unrestricted cash (NZD)',p.ratios?.unrestrictedCash,'number','min="0" step="0.01"')}${input('timing','Desired close date',p.funding.desiredCloseDate,'date')}${input('authority','Borrower authority / evidence',p.funding.authority||'')}${textarea('confidentiality','Confidentiality / disclosure requirements',p.funding.confidentiality||'')}`;}
function blankProfile(){return {synthetic:true,company:{name:'',industry:null,location:null},funding:{amount:null,currency:'NZD',purpose:null,purposes:[],termMonths:null,security:[],targetBasis:'facility_limits'},financials:{annualRevenue:{amount:null},ebitda:{amount:null}},documents:[],review:{fields:{},conflicts:[],confirmedFields:[],proposedValues:{}}};}
function newDealView(){return head('New deal','Save a draft now. Add documents and confirm the details when ready.')+`<section class="panel"><form data-form="create"><div class="form-grid">${input('deal_name','Deal name','','text','required maxlength="300"')}${select('template','Start with',[{id:'blank',name:'Blank draft'},{id:'thirty',name:'Fictional NZ$30m acquisition'},{id:'kowhai',name:'Fictional Kowhai document example'}],'blank')}</div><div id="intake-fields" class="form-grid spaced">${profileFields(blankProfile())}</div>${formButtons('Save draft')}</form></section>`;}
function dealView(tab){const d=detail.deal,p=d.profile,run=recentRun(),due=detail.deal_matches.filter(m=>m.next_follow_up_at).sort((a,b)=>new Date(a.next_follow_up_at)-new Date(b.next_follow_up_at));const stale=run&&run.profile_version!==d.profile_version;
 return head(d.deal_name,`${p.company.name||'Borrower to confirm'} · ${p.company.industry||'Industry to confirm'} · ${p.company.location||'Location to confirm'}`,`<a class="btn" href="#deals">All deals</a>`)+`<div class="readiness">${badge(d.overall_stage)}<span>${money(p.funding.amount)} requested</span><span>Owner: ${esc(userName(d.assigned_user_id))}</span><span>Profile version ${d.profile_version} · ${d.confirmed_version===d.profile_version?'Confirmed':'Needs review'}</span></div>${stale?'<p class="banner warn spaced">The profile changed after the last comparison. Earlier scores and reports are preserved; compare again before using them.</p>':''}<nav class="tabs" aria-label="Deal sections">${[['summary','Deal overview'],['matches','Capital matches'],['funding','Funding & terms'],['documents','Documents & review'],['activity','Notes & history']].map(([k,n])=>`<a href="${dealLink(d.id,k)}" class="${tab===k?'active':''}">${n}</a>`).join('')}</nav>${tab==='matches'?matchesView():tab==='funding'?fundingView():tab==='documents'?documentsView():tab==='activity'?notesView():summaryView(due)}`;
}
function summaryView(due){const d=detail.deal,p=d.profile,latest=recentRun(),summary=latest?.snapshot?.legacy?.summary?.text;return `<div class="split"><div><section class="panel"><div class="panel-head"><h2>Funding request</h2><a href="${dealLink(d.id,'documents')}">Review documents</a></div><dl class="definition">${[['Finance sought',money(p.funding.amount)],['Purpose',p.funding.purpose],['Requested term',p.funding.termMonths?`${p.funding.termMonths} months`:null],['Revenue',money(p.financials.annualRevenue.amount)],['EBITDA',money(p.financials.ebitda.amount)],['Reporting period',date(p.financials.ebitda.periodEnd)],['Security',(p.funding.security||[]).join(', ')],['Debt ratio',p.ratios?.leverage!=null?`${p.ratios.leverage}x · ${label(p.ratios.leverageType)}`:null],['Desired close',date(p.funding.desiredCloseDate)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'Not supplied')}</dd></div>`).join('')}</dl><details class="spaced"><summary>Edit deal details</summary><form data-form="profile"><div class="form-grid spaced">${profileFields(p)}</div>${formButtons('Save profile changes')}</form></details></section><section class="panel"><h2>Review & compare</h2><p>${summary?esc(summary):'Confirm the source details, then run an explainable comparison against recorded lender criteria.'}</p><div class="actions"><button class="primary" data-action="confirm">Confirm Deal Profile</button><button data-action="analyze">Compare lenders</button></div><p class="muted spaced">Comparisons use the reviewed information and recorded fictional criteria. No lender is contacted.</p></section><section class="panel"><h2>Supporting profile information</h2>${detail.source_records.length?detail.source_records.reduce((out,r)=>{if(!out.some(x=>x.kind===r.kind))out.push(r);return out;},[]).map(r=>`<details><summary>${esc(label(r.kind))}</summary>${detail.source_records.filter(x=>x.kind===r.kind).map(x=>`<dl class="definition">${Object.entries(x.data).filter(([k,v])=>v!==''&&!['synthetic'].includes(k)).map(([k,v])=>`<div><dt>${esc(label(k))}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`).join('')}</details>`).join(''):empty('Supporting records appear here as documents and data are added.')}</section></div><aside><section class="panel"><h2>Deal owner & stage</h2><form data-form="workflow">${select('stage','Overall stage',stages,d.overall_stage)}<div class="spaced">${select('assigned_user_id','Assigned broker',appData.users,d.assigned_user_id)}</div><div class="spaced">${textarea('outcome_note','Outcome / closing evidence')}</div>${formButtons('Save stage')}</form></section><section class="panel"><h2>Upcoming follow-ups</h2>${due.length?due.slice(0,3).map(followItem).join(''):empty('Set a follow-up in Capital matches.')}</section></aside></div>`;}
function checksTable(r){return r.checks?.length?`<div class="table-scroll"><table><thead><tr><th>Criterion</th><th>Deal value</th><th>Recorded requirement</th><th>Finding</th></tr></thead><tbody>${r.checks.map(c=>`<tr><td>${esc(label(c.field))}</td><td>${esc(typeof c.value==='object'?JSON.stringify(c.value):c.value??'Unknown')}</td><td>${esc(typeof c.requirement==='object'?JSON.stringify(c.requirement):c.requirement??'Unknown')}</td><td>${badge(c.outcome,c.outcome==='outside_criteria'?'bad':c.outcome==='needs_check'?'warn':'')}</td></tr>`).join('')}</tbody></table></div>`: `<p>${esc((r.reasons||[]).join('; ')||'Detailed criteria were not recorded with this historical result.')}</p>`;}
function matchesView(){
 const run=recentRun(),d=detail.deal,results=detail.match_results.filter(r=>r.run_id===run?.id).sort((a,b)=>(a.result.rank??100)-(b.result.rank??100)||(b.result.score??0)-(a.result.score??0));
 const selected=detail.packages.find(p=>p.id===d.preferred_package_id)?.snapshot.alternatives[d.preferred_alternative];
 return `<section class="panel"><div class="panel-head"><div><h2>Capital matches</h2><small>${results.length} providers considered · original evidence retained</small></div><div class="actions"><button data-action="analyze">Compare again</button>${run&&!run.saved_at?'<button class="primary" data-action="save-matches">Save matches</button>':''}</div></div>${run?`<p class="muted">${date(run.created_at,true)} · profile v${run.profile_version} · ${run.saved_at?'Saved to this workspace':'Save these results to start tracking providers.'}</p>`:''}${results.length?`<div class="table-scroll"><table class="matches-table"><thead><tr><th>Capital provider / fit</th><th>Current status</th><th>Proposed</th><th>Last action</th><th>Follow-up</th><th>Broker</th></tr></thead><tbody>${results.map(row=>{
  const r=row.result,m=detail.deal_matches.find(m=>m.provider_id===row.provider_id),original=detail.match_results.find(x=>x.id===m?.original_result_id)?.result,last=detail.deal_events.find(e=>e.deal_match_id===m?.id),allocations=selected?.allocations.filter(a=>a.provider_id===row.provider_id);
 return `<tr><td><button class="provider-link" data-internal-report="${esc(row.id)}">${esc(r.provider_name)}</button><div>${r.score!=null?`<span class="score">${r.score} / 100</span>`:badge(r.outcome,r.outcome==='outside_criteria'?'bad':r.outcome==='needs_check'?'warn':'')}</div><small>${esc(r.score_source||'Recorded criteria')}</small>${original&&m.original_result_id!==row.id?`<small>Original: ${esc(original.score??label(original.outcome))} · history preserved</small>`:''}</td><td>${m?`<label class="sr-only" for="status-${esc(m.id)}">Status for ${esc(r.provider_name)}</label><select id="status-${esc(m.id)}" class="status-select" data-status="${esc(m.id)}">${opt(statuses,m.status)}</select>`:badge('Not saved')}</td><td class="num">${allocations?.length?money(allocations.reduce((n,a)=>n+a.amount_cents,0)/100):'—'}</td><td>${last?esc(label(last.new_status||last.event_type)):'—'}<small>${date(last?.occurred_at)}</small></td><td>${date(m?.next_follow_up_at)}${m&&overdue(m)?'<small>Overdue</small>':''}</td><td>${m?esc(userName(m.assigned_user_id)):'—'}</td></tr><tr class="match-expanded"><td colspan="6"><details id="provider-${esc(m?.id||row.id)}"><summary>Fit, actions & follow-up · ${esc(r.provider_name)}</summary>${checksTable(r)}<p class="muted spaced">Mandate ${esc(r.mandate_id)} · ${esc(r.mandate_snapshot?.data?.source||'Source not recorded')}</p><div class="actions"><button class="small" data-report="${esc(row.id)}">Create shareable report</button><button class="small" data-internal-report="${esc(row.id)}">Internal report with history</button><a href="#provider/${encodeURIComponent(r.provider_id)}/${encodeURIComponent(d.id)}">Provider history</a></div>${m?providerForm(m):''}</details></td></tr>`;
 }).join('')}</tbody></table></div>`:empty('Confirm the Deal Profile, then compare lenders.')}</section>${detail.deal_matches.some(m=>!results.some(r=>r.provider_id===m.provider_id))?`<section class="panel"><h2>Earlier provider relationships</h2><p class="muted">These relationships are retained when absent from the latest run.</p>${detail.deal_matches.filter(m=>!results.some(r=>r.provider_id===m.provider_id)).map(m=>`<details><summary>${esc(providerName(m.provider_id))} · ${label(m.status)}</summary>${providerForm(m)}</details>`).join('')}</section>`:''}<section class="panel"><h2>Saved comparison runs</h2>${detail.matching_runs.map(r=>`<details><summary>${date(r.created_at,true)} · profile v${r.profile_version} · ${r.saved_at?'Saved':'Unsaved'}</summary>${detail.match_results.filter(x=>x.run_id===r.id).map(x=>`<p>${esc(x.result.provider_name)} · ${x.result.score??label(x.result.outcome)} <button class="small" data-report="${esc(x.id)}">Report</button></p>`).join('')}</details>`).join('')}</section>`;
}
function providerForm(m){return `<form data-form="provider" data-id="${esc(m.id)}" class="spaced"><div class="form-grid">${select('status','Status',statuses,m.status)}${select('decline_reason','Decline reason (optional)',declines,m.decline_reason,'No reason supplied')}${input('last_contacted_at','Last contacted',asDate(m.last_contacted_at),'date')}${input('next_follow_up_at','Next follow-up',asDate(m.next_follow_up_at),'date')}${select('selection','Approach shortlist',['considering','shortlisted','dismissed'],m.selection)}${select('assigned_user_id','Assigned broker',appData.users,m.assigned_user_id)}${textarea('follow_up_note','Follow-up note',m.follow_up_note)}${textarea('note','Add a provider note')}</div>${formButtons('Save provider activity')}<button type="submit" name="without_reason" value="true" class="small">Mark declined without a reason</button></form>`;}
function documentsView(){const p=detail.deal.profile,fields=Object.entries(p.review?.fields||{});return `<section class="panel"><h2>Documents & sources</h2><p>Upload the supported fictional CSVs. Values remain proposals until you review them.</p><form data-form="upload"><label>Choose up to five CSV files<input name="files" type="file" accept=".csv" multiple required></label>${formButtons('Read and save documents')}</form><details class="spaced"><summary>Download fictional borrower examples</summary><div class="actions">${['company-overview','management-accounts','accountant-summary','equipment-quote','funding-request'].map(n=>`<a class="btn small" href="/prototype/synthetic-data/borrower-documents/kowhai-${n}.csv" download>${label(n.replaceAll('-',' '))}</a>`).join('')}</div></details>${detail.documents.map(d=>`<div class="next-item"><a href="/api/documents/${encodeURIComponent(d.id)}">${esc(d.filename)}</a><small> · ${d.facts.length} extracted fields · ${date(d.created_at)}</small></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>Review extracted values</h2><button class="primary" data-action="confirm">Confirm Deal Profile</button></div>${fields.length?fields.map(([field,state])=>{const path=field.startsWith('financials.')?field+'.amount':field,current=path.split('.').reduce((v,k)=>v?.[k],p);return `<div class="next-item"><div class="actions"><strong>${esc(label(field.replaceAll('.',' ')))}</strong>${badge(state.status,state.status==='confirmed'?'':'warn')}</div><p>Current: ${esc(Array.isArray(current)?current.join(', '):current??'Not supplied')}</p><div class="source-values"><button data-resolve="${esc(field)}">Keep / confirm current value</button>${detail.documents.flatMap(d=>d.facts.filter(f=>f.field===field).map(f=>`<button data-resolve="${esc(field)}" data-document="${esc(d.id)}" data-row="${f.row}">Use ${esc(Array.isArray(f.value)?f.value.join(', '):f.value)} · ${esc(d.filename)} · row ${f.row}${f.periodEnd?' · '+esc(f.periodEnd):''}</button>`)).join('')}</div></div>`;}).join(''):empty('Upload documents to review proposed values, or confirm the details entered in Deal overview.')}</section>`;}
function notesView(){return `<div class="split"><section class="panel"><h2>Activity timeline</h2>${timeline(detail.deal_events)}</section><aside><section class="panel"><h2>Add a note</h2><form data-form="note">${select('match_id','Attach to',detail.deal_matches.map(m=>({id:m.id,name:providerName(m.provider_id)})),'','Overall deal')}${textarea('note_text','Broker note')}${formButtons('Save note')}</form></section><section class="panel"><h2>Broker notes</h2>${detail.deal_notes.length?detail.deal_notes.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(n=>`<div class="next-item"><small>${esc(userName(n.user_id))} · ${date(n.created_at,true)}</small><p class="notes">${esc(n.note_text)}</p></div>`).join(''):empty('No notes recorded.')}</section></aside></div>`;}
function facilityList(p=detail.deal.profile){return p.facilities?.length?p.facilities:[{id:'main',name:'Requested facility',...p.funding,type:p.funding.type||'term_loan'}];}
function currentRecords(records){const revised=new Set(records.map(r=>r.supersedes_id).filter(Boolean));return records.filter(r=>!revised.has(r.id)&&r.state!=='withdrawn'&&(!r.expires_at||new Date(r.expires_at)>new Date()));}
function packageWarnings(p){const out=[];for(const issue of detail.participation_issues||[])if(p.snapshot.alternatives.some(x=>x.allocations.some(a=>a.provider_id===issue.provider_id&&a.facility_id===issue.facility_id)))out.push(providerName(issue.provider_id)+': '+issue.reason+'.');if(p.profile_version!==detail.deal.profile_version)out.push('Deal Profile has changed. Compare again and create a new scenario.');for(const a of p.snapshot.alternatives.flatMap(x=>x.allocations)){const provider=detail.providers.find(x=>x.id===a.provider_id),m=detail.deal_matches.find(x=>x.provider_id===a.provider_id);if(['DECLINED','WITHDRAWN'].includes(m?.status))out.push(providerName(a.provider_id)+' is now '+label(m.status).toLowerCase());if(provider?.mandate.id!==a.mandate_id)out.push(providerName(a.provider_id)+' has a newer mandate.');if(provider?.mandate.data.validUntil&&new Date(provider.mandate.data.validUntil)<=new Date())out.push(providerName(a.provider_id)+' participation has expired.');}return [...new Set(out)];}
function fundingView(){const d=detail.deal,fs=facilityList(),run=recentRun(true),p=detail.packages.toSorted((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0],cov=detail.coverage;const active=currentRecords(detail.funding_records);return `<div class="ledger"><div><small>Documented active commitments</small><strong>${money(cov.commitment/100)}</strong></div><div><small>Conditional commitments</small><strong>${money(cov.conditional/100)}</strong></div><div><small>Actual funding recorded</small><strong>${money(cov.funding/100)}</strong></div></div><section class="panel"><h2>Funding structure</h2><p class="muted">Facility limits and cash drawable at closing are separate. Proposed packages do not count as commitments.</p><details><summary>Edit requested facilities and closing needs</summary><form data-form="facilities"><div class="form-grid spaced">${select('targetBasis','Requested amount represents',['facility_limits','cash_at_close'],d.profile.funding.targetBasis)}${input('refinancePayoffs','Debt payoffs at closing (NZD)',d.profile.funding.refinancePayoffs??0,'number','min="0" step="0.01"')}${input('closingFees','Fees paid at closing (NZD)',d.profile.funding.closingFees??0,'number','min="0" step="0.01"')}${input('roles','Proposed arranger / agent / trustee',d.profile.funding.roles||'')}</div><div id="facility-rows">${fs.map(f=>facilityForm(f)).join('')}</div><div class="actions spaced"><button type="button" data-action="add-facility">Add facility</button><label class="check"><input type="checkbox" name="rolesConfirmed" ${d.profile.funding.rolesConfirmed?'checked':''}>Appointments confirmed</label><label class="check"><input type="checkbox" name="crossFacilitySecurityConfirmed" ${d.profile.funding.crossFacilitySecurityConfirmed?'checked':''}>Cross-facility priority reviewed</label></div>${formButtons('Save financing structure')}</form></details><div class="table-scroll"><table><thead><tr><th>Facility / purpose</th><th>Limit</th><th>Cash at closing</th><th>Term / security</th></tr></thead><tbody>${fs.map(f=>`<tr><td>${esc(f.name)}<small>${esc(label(f.type))} · ${esc((f.purposes||[]).join(', '))}</small></td><td>${money(f.amount)}</td><td>${money(f.drawAtClose)}</td><td>${f.termMonths??'Unknown'} months<small>${esc((f.security||[]).join(', '))}</small></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Explore funding packages</h2>${p?badge(p.snapshot.exhaustive?'Complete search':'Bounded search','warn'):''}</div>${!run?'<p class="banner">Save matching results before creating a package.</p>':''}<form data-form="package"><div class="form-grid">${input('name','Scenario name','Funding options')}${select('mode','Scenario preference',[{id:'all',name:'Compare single and multiple providers'},{id:'club',name:'Explore multi-provider options'}],'all')}</div><details class="spaced"><summary>Pin, exclude or lock allocations</summary><p class="muted">Pin requires a provider to appear. A locked amount must fit the provider’s documented limits.</p><div class="table-scroll"><table><thead><tr><th>Provider</th><th>Preference</th><th>Lock amount (NZD)</th><th>Facility for lock</th></tr></thead><tbody>${detail.providers.filter(p=>p.mandate.data.participationMax!=null).map(p=>`<tr><td>${esc(p.name)}</td><td><select aria-label="Preference for ${esc(p.name)}" name="pref:${esc(p.id)}">${opt(['consider','pin','exclude'],'consider')}</select></td><td><input aria-label="Locked amount for ${esc(p.name)}" name="lock:${esc(p.id)}" type="number" min="0.01" step="0.01"></td><td><select aria-label="Locked facility for ${esc(p.name)}" name="facility:${esc(p.id)}">${opt(fs,'')}</select></td></tr>`).join('')}</tbody></table></div></details>${formButtons('Find and save package options')}</form></section>${p?packageView(p):''}<section class="panel"><div class="panel-head"><h2>Terms & funding evidence</h2><small>Amounts below describe different stages; they are never added together.</small></div>${active.length?termsTable(active):empty('No lender indications, terms, commitments or funding recorded.')}<details class="spaced"><summary>Record or revise lender evidence</summary><form data-form="funding"><div class="form-grid spaced">${select('match_id','Provider',detail.deal_matches.map(m=>({id:m.id,name:providerName(m.provider_id)})),null,'Choose provider')}${select('facility_id','Facility',fs,fs[0]?.id)}${select('kind','Record type',['indication','terms','commitment','funding'],'terms')}${select('state','Evidence state',['indicative','conditional','active','withdrawn','funded'],'indicative')}${input('amount','Amount (NZD)','','number','required min="0" step="0.01"')}${input('expires_at','Expiry','','date')}${select('supersedes_id','Replaces previous record',active.map(r=>({id:r.id,name:providerName(detail.deal_matches.find(m=>m.id===r.deal_match_id)?.provider_id)+' · '+r.kind+' · '+money(Number(r.amount_cents)/100)})),null,'New record')}${input('source','Source document / evidence','','text','required')}${input('rate','Fixed interest rate, if quoted')}${input('benchmark','Floating benchmark')}${input('margin','Margin, if quoted')}${input('received_date','Received date','','date')}${input('term','Offered term / availability')}${input('repayment','Repayment structure')}${input('security','Security / guarantees / ranking')}${input('floors','Rate floor / cash / PIK components')}${textarea('fees','Upfront, ongoing, commitment, exit and agency fees')}${textarea('conditions','Covenants and material conditions')}</div><p class="muted">Use Active for a documented commitment, Conditional while conditions remain, and Funded only for actual funds received. A mandate’s target return is not a quoted borrower rate.</p>${formButtons('Save evidence record')}</form></details></section><section class="panel"><h2>Due diligence & closing checklist</h2>${detail.tasks.map(t=>`<details><summary>${t.completed?'Completed · ':''}${esc(t.title)} · ${date(t.due_at)}</summary><form data-form="task" data-id="${esc(t.id)}"><div class="form-grid">${input('title','Task',t.title)}${select('assigned_user_id','Owner',appData.users,t.assigned_user_id)}${input('due_at','Due date',asDate(t.due_at),'date')}${textarea('evidence','Completion evidence',t.evidence)}<label class="check"><input type="checkbox" name="completed" ${t.completed?'checked':''}>Complete</label></div>${formButtons('Update task')}</form></details>`).join('')}<details class="spaced"><summary>Add condition or information request</summary><form data-form="task"><div class="form-grid">${input('title','Task','','text','required')}${select('assigned_user_id','Owner',appData.users,appData.user.id)}${input('due_at','Due date','','date')}</div>${formButtons('Add task')}</form></details></section>${detail.packages.length>1?`<section class="panel"><h2>Earlier scenarios</h2>${detail.packages.filter(x=>x.id!==p.id).map(x=>`<details><summary>${esc(x.name)} · ${date(x.created_at,true)}</summary>${packageView(x)}</details>`).join('')}</section>`:''}`;}
function facilityForm(f){return `<fieldset class="facility-form spaced" data-id="${esc(f.id)}"><legend>${esc(f.name||'New facility')}</legend><div class="form-grid">${input('facility_name','Facility name',f.name)}${input('facility_amount','Facility limit (NZD)',f.amount,'number','min="0.01" step="0.01" required')}${select('facility_type','Facility type',['term_loan','revolver','equipment_finance','property_finance'],f.type)}${input('facility_draw','Cash available at closing (NZD)',f.drawAtClose,'number','min="0" step="0.01"')}${input('facility_term','Term in months',f.termMonths,'number','min="1"')}${input('facility_purposes','Purpose categories',(f.purposes||[]).join(', '))}${input('facility_security','Security',(f.security||[]).join(', '))}${input('facility_date','Required availability date',f.requiredDate||'','date')}</div><button class="small spaced" type="button" data-remove-facility>Remove facility</button></fieldset>`;}
function packageView(p){const s=p.snapshot,warnings=packageWarnings(p);return `<section class="panel"><div class="panel-head"><h2>${esc(p.name)}</h2><small>Profile v${p.profile_version} · ${date(p.created_at,true)}</small></div>${warnings.map(w=>`<p class="banner warn">${esc(w)}</p>`).join('')}<p>${esc(s.message)}</p>${warnings.length?'<p class="banner warn">This saved proposal needs review. Its original allocations remain visible as history.</p>':''}${s.target_basis==='cash_at_close'?`<p>Facility limits: ${money(s.target_cents/100)} · net cash required at closing: ${money(s.requested_cash_cents/100)}</p>`:''}${s.alternatives.length?s.alternatives.map((a,i)=>`<div class="package"><div class="panel-head"><h3>${a.provider_count===1?'Single provider':a.provider_count+' providers'} · ${money(a.total_cents/100)} proposed</h3>${badge(a.status,a.warnings.length?'warn':'')}</div><p>${esc(a.explanation)}</p><div class="table-scroll"><table><thead><tr><th>Provider</th><th>Facility</th><th>Proposed allocation</th></tr></thead><tbody>${a.allocations.map(x=>`<tr><td>${esc(x.provider_name)}</td><td>${esc(x.facility_name)}</td><td class="num">${money(x.amount_cents/100)}</td></tr>`).join('')}</tbody></table></div>${a.warnings.length?`<p class="spaced">Open checks</p><ul>${a.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}${detail.deal.preferred_package_id===p.id&&detail.deal.preferred_alternative===i?badge(warnings.length?'Preferred option · needs review':'Preferred option',warnings.length?'warn':''):!warnings.length?`<form data-form="choose-package" data-id="${esc(p.id)}" data-alternative="${i}">${input('reason','Why this option?','','text','required')}${formButtons('Set as preferred proposal')}</form>`:''}</div>`).join(''):`<p class="banner warn">Uncovered facility amount: ${money(s.shortfall_cents/100)}.</p>`}<details class="spaced"><summary>Search evidence and excluded providers</summary><p>${s.searched} combinations assessed · ${s.exhaustive?'Exhaustive for the eligible catalogue':'Search limit reached; no whole-catalogue conclusion'}.</p>${s.exclusions.map(e=>`<p>${esc(e.provider)}${e.facility?' · '+esc(e.facility):''}: ${esc(e.reason)}</p>`).join('')}</details></section>`;}
function termsTable(records){return `<div class="table-scroll"><table><thead><tr><th>Provider / facility</th><th>Type / state</th><th>Amount</th><th>Pricing</th><th>Repayment / security / conditions</th><th>Expiry</th></tr></thead><tbody>${records.map(r=>{const m=detail.deal_matches.find(m=>m.id===r.deal_match_id);return `<tr><td>${esc(providerName(m?.provider_id))}<small>${esc(facilityList().find(f=>f.id===r.facility_id)?.name)}</small><small>Evidence: ${esc(r.data.source)}</small></td><td>${badge(r.kind)}<small>${esc(label(r.state))}</small></td><td class="num">${money(Number(r.amount_cents)/100)}</td><td>${esc(r.data.rate||[r.data.benchmark,r.data.margin].filter(Boolean).join(' + ')||'Not supplied')}<small>Fees: ${esc(r.data.fees||'Not supplied')}</small></td><td>${esc(r.data.repayment||'Not supplied')}<small>${esc(r.data.security||'Security not supplied')}</small><small>${esc(r.data.conditions||'Conditions not supplied')}</small>${r.kind==='terms'?`${detail.deal.preferred_terms_id===r.id?badge('Preferred terms'):`<details><summary>Select terms</summary><form data-form="choose-terms" data-id="${esc(r.id)}">${input('reason','Reason for selection','','text','required')}${formButtons('Save preferred terms')}</form></details>`}`:''}</td><td>${date(r.expires_at)}</td></tr>`;}).join('')}</tbody></table></div><p class="muted spaced">No all-in cost comparison is calculated: comparable drawdown, fee and pricing assumptions have not been provided.</p>`;}
function providersView(){return head('Capital providers','Your accessible directory, with dated mandate evidence and brokerage history.')+`<form class="filters" data-form="filter-providers">${input('search','Find a capital provider','','search')}<button>Search</button></form><section class="panel" id="provider-directory">${providerDirectory(appData.providers)}</section>`;}
function providerDirectory(ps){return ps.length?`<div class="table-scroll"><table><thead><tr><th>Provider</th><th>Industries</th><th>Recorded amount scope</th><th>Mandate effective</th></tr></thead><tbody>${ps.map(p=>`<tr><td><a href="#provider/${encodeURIComponent(p.id)}">${esc(p.name)}</a><small>Fictional provider</small></td><td>${esc((p.mandate.data.sectors||[]).join(', ')||'Not supplied')}</td><td>${esc(label(p.mandate.data.amountScope))}<small>${money(p.mandate.data.participationMax??p.mandate.data.maxDeal)} maximum</small></td><td>${date(p.mandate.effective_from)}</td></tr>`).join('')}</tbody></table></div>`:empty('No providers match this search.');}
function historyView(h){const pct=n=>n==null?'Not enough data':new Intl.NumberFormat('en-NZ',{style:'percent',maximumFractionDigits:1}).format(n);return `<div class="history-grid">${[['Matched',h.matched],['Contacted',h.contacted],['Explicitly interested',h.interested],['Declined',h.declined],['Terms received',h.terms],['Closed',h.closed]].map(([k,v])=>`<div><strong>${v}</strong><small>${k}</small></div>`).join('')}</div><div class="ledger"><div><small>Interest / contacted</small><strong>${pct(h.interest_rate)}</strong><small>${h.interest_numerator} of ${h.contacted} recorded contacts</small></div><div><small>Decline / contacted</small><strong>${pct(h.decline_rate)}</strong><small>${h.decline_numerator} of ${h.contacted} recorded contacts</small></div><div><small>Median first response</small><strong>${h.median_days==null?'Not enough data':h.median_days.toFixed(1)+' days'}</strong><small>${h.response_sample} supported intervals</small></div></div><p class="muted">Each relationship counts once per milestone. Interest and decline can both occur on one deal, so rates need not add to 100%. Missing contacts are never inferred.</p>${[['By industry',h.industries],['By deal size',h.bands]].map(([title,data])=>`<h3 class="spaced">${title}</h3>${Object.keys(data).length?`<div class="table-scroll"><table><thead><tr><th>Group</th><th>Deals</th><th>Contacted</th><th>Interested</th><th>Declined</th></tr></thead><tbody>${Object.entries(data).map(([name,n])=>`<tr><td>${esc(name)}</td><td>${n.matched}</td><td>${n.contacted}</td><td>${n.interested}</td><td>${n.declined}</td></tr>`).join('')}</tbody></table></div>`:empty('Not enough data.')}`).join('')}<h3 class="spaced">Recorded insights</h3>${h.contacted?`<p>Your firm has approached this provider on ${h.contacted} distinct transaction${h.contacted===1?'':'s'}.</p>`:empty('No recorded approaches yet.')}${Object.entries(h.reasons).map(([r,n])=>`<p>${n} transaction${n===1?'':'s'} declined with reason: ${esc(label(r).toLowerCase())}.</p>`).join('')}<p class="muted">Most recent interaction: ${date(h.recent?.occurred_at,true)}. Historical outcomes do not alter matching scores.</p>`;}
function providerView(p,h){return head(p.name,'Fictional mandate evidence and outcomes within your brokerage.',`<a class="btn" href="#providers">All providers</a>`)+`<section class="panel"><h2>Historical responses</h2>${historyView(h)}</section><section class="panel"><h2>Current recorded mandate</h2><p>Version ${esc(p.mandate.id)} · effective ${date(p.mandate.effective_from)}</p><dl class="definition">${Object.entries(p.mandate.data).filter(([k])=>!['legacy','synthetic'].includes(k)).map(([k,v])=>`<div><dt>${esc(label(k.replace(/[A-Z]/g,m=>' '+m)))}</dt><dd>${esc(v==null?'Not supplied':Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v)}</dd></div>`).join('')}</dl><details class="spaced"><summary>Add a sourced mandate version</summary><p class="muted">The new version affects future comparisons. Historical matches remain unchanged.</p><form data-form="mandate" data-id="${esc(p.id)}"><div class="form-grid">${input('source','Source and verification evidence','','text','required')}${input('effective_from','Effective from',asDate(new Date()),'date','required')}${input('participationMin','Minimum participation (NZD)',p.mandate.data.participationMin,'number','min="0" step="0.01"')}${input('participationMax','Maximum participation (NZD)',p.mandate.data.participationMax,'number','min="0" step="0.01"')}${input('availableCapital','Available capital (NZD)',p.mandate.data.availableCapital,'number','min="0" step="0.01"')}${input('capacityAsAt','Capital last checked',asDate(p.mandate.data.capacityAsAt),'date')}${select('coLend','Will lend alongside others',[{id:'unknown',name:'Needs confirmation'},{id:'true',name:'Documented yes'},{id:'false',name:'Documented no'}],p.mandate.data.coLend==null?'unknown':String(p.mandate.data.coLend))}${input('securityGroup','Documented shared-security arrangement',p.mandate.data.securityGroup)}</div>${formButtons('Save new mandate version')}</form></details></section>`;}
function reportView(report){const s=report.snapshot,r=s.result,profile=s.profile;return `<article class="report">${head('Provider explanation',s.deal_name+' · '+r.provider_name,`<div class="actions no-print"><a class="btn primary" href="/api/reports/${encodeURIComponent(report.id)}.pdf" download>Download PDF</a><button data-action="print">Print preview</button></div>`)}<p class="banner">${esc(s.disclaimer)} ${report.audience==='internal'?'Internal brokerage report: contains private outcome history.':'Shareable version: broker notes and private outcome history are excluded.'}</p><section class="panel"><h2>Analysis record</h2><dl class="definition">${[['Borrower',profile.company.name],['Requested',money(profile.funding.amount)],['Profile version',s.profile_version],['Analysis time',date(s.analysis_date,true)],['Mandate version',r.mandate_id],['Score',r.score!=null?`${r.score} / ${r.score_scale||'recorded scale'} · ${r.score_source}`:'No numeric score supplied']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${s.stale_at_creation?'<p class="banner warn">A newer Deal Profile or mandate existed when this historical report was saved.</p>':''}</section><section class="panel"><h2>Fit, constraints & unknowns</h2>${checksTable(r)}<p class="muted spaced">Evidence: ${esc(r.mandate_snapshot?.data?.source||'Recorded synthetic history')}. Values reflect the saved profile and mandate, not a current offer.</p></section><section class="panel"><h2>Proposed allocation & received terms</h2>${s.allocations?.length?s.allocations.map(a=>`<p>${esc(a.facility_name)}: ${money(a.amount_cents/100)} proposed; roles ${esc(s.roles||'need confirmation')}.</p>`).join(''):empty('No preferred package allocation recorded for this result.')} ${s.terms.length?s.terms.map(t=>`<p>${money(Number(t.amount_cents)/100)} · ${esc(label(t.state))} · expires ${date(t.expires_at)}</p><dl class="definition">${Object.entries(t.data).map(([k,v])=>`<div><dt>${esc(label(k))}</dt><dd>${esc(v||'Not supplied')}</dd></div>`).join('')}</dl>`).join(''):empty('No current terms have been recorded.')}</section>${s.history?`<section class="panel"><h2>Previous transactions · current deal excluded</h2>${historyView(s.history)}</section>`:''}<section class="panel"><h2>Recommended next actions</h2><ol><li>Resolve any missing or conflicting source information.</li><li>Confirm current lender appetite, capacity, security priority and relevant consents.</li><li>Record borrower authority before sharing confidential information.</li><li>Request transaction-specific terms and record conditions and expiry.</li></ol></section><p class="disclaimer">Saved ${date(report.created_at,true)}. Report ID ${esc(report.id)}. This immutable snapshot will not change when later information is recorded.</p></article>`;}
const split=v=>v.split(',').map(x=>x.trim()).filter(Boolean),num=v=>v===''?null:Number(v);
function profileFrom(form,base){const f=new FormData(form),p=structuredClone(base);p.ratios={...p.ratios,existingDebt:num(f.get('existingDebt')),unrestrictedCash:num(f.get('cash'))};p.company={...p.company,name:f.get('company_name'),industry:f.get('industry')||null,location:f.get('location')||null,country:f.get('country')||null};p.funding={...p.funding,amount:num(f.get('amount')),purpose:f.get('purpose')||null,purposes:split(f.get('purposes')),termMonths:num(f.get('term')),security:split(f.get('security')),desiredCloseDate:f.get('timing')||null,authority:f.get('authority')||null,confidentiality:f.get('confidentiality')||null};p.financials.annualRevenue={...p.financials.annualRevenue,amount:num(f.get('revenue')),periodEnd:f.get('period')||null,currency:'NZD'};p.financials.ebitda={...p.financials.ebitda,amount:num(f.get('ebitda')),periodEnd:f.get('period')||null,currency:'NZD'};return p;}
async function act(action,body={}){return api('/deals/'+encodeURIComponent(detail.deal.id)+'/'+action,{version:detail.deal.version,...body});}
async function refresh(message){await route();if(message)notify(message);}
document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])'),error=form.querySelector('.error');if(error)error.textContent='';if(button)button.disabled=true;try{const f=new FormData(form),data=Object.fromEntries(f),kind=form.dataset.form;
 if(kind==='login'){await api('/login',data);await route();return;}
 if(kind==='filter-deals'){const ds=appData.deals.filter(d=>(!data.search||JSON.stringify([d.deal_name,d.profile.company]).toLowerCase().includes(data.search.toLowerCase()))&&(!data.stage||d.overall_stage===data.stage)&&(!data.broker||d.assigned_user_id===data.broker)&&(!data.industry||d.profile.company.industry===data.industry)&&(data.due!=='overdue'||appData.deal_matches.some(m=>m.deal_id===d.id&&overdue(m)))).sort((a,b)=>data.sort==='amount'?(b.profile.funding.amount||0)-(a.profile.funding.amount||0):new Date(b[data.sort==='created'?'created_at':'updated_at'])-new Date(a[data.sort==='created'?'created_at':'updated_at']));$('#deal-table').innerHTML=dealTable(ds,true);return;}
 if(kind==='filter-providers'){$('#provider-directory').innerHTML=providerDirectory(appData.providers.filter(p=>p.name.toLowerCase().includes(data.search.toLowerCase())));return;}
 if(kind==='create'){const result=await api('/deals',{deal_name:data.deal_name,profile:profileFrom(form,data.template==='thirty'?appData.deals.find(d=>d.id==='DEAL-30M')?.profile||blankProfile():data.template==='kowhai'?appData.deals.find(d=>d.id==='DEAL-KOWHAI-001')?.profile||blankProfile():blankProfile())});location.hash=dealLink(result.id);notify('Draft saved');return;}
 if(kind==='profile')await act('profile',{profile:profileFrom(form,detail.deal.profile)});
 if(kind==='workflow')await act('workflow',data);
 if(kind==='upload'){const files=[...form.elements.files.files];await act('upload',{files:await Promise.all(files.map(async file=>({name:file.name,content:await file.text()})))});}
 if(kind==='note')await act('note',data);
 if(kind==='provider'){const m=detail.deal_matches.find(m=>m.id===form.dataset.id);await act('provider',{...data,match_id:m.id,match_version:m.version,status:event.submitter?.name==='without_reason'?'DECLINED':data.status,decline_reason:event.submitter?.name==='without_reason'?null:data.decline_reason||null,last_contacted_at:data.last_contacted_at===asDate(m.last_contacted_at)?m.last_contacted_at:iso(data.last_contacted_at),next_follow_up_at:data.next_follow_up_at===asDate(m.next_follow_up_at)?m.next_follow_up_at:iso(data.next_follow_up_at)});}
 if(kind==='facilities'){const p=structuredClone(detail.deal.profile);p.funding={...p.funding,targetBasis:data.targetBasis,refinancePayoffs:num(data.refinancePayoffs),closingFees:num(data.closingFees),roles:data.roles,rolesConfirmed:f.has('rolesConfirmed'),crossFacilitySecurityConfirmed:f.has('crossFacilitySecurityConfirmed')};p.facilities=[...form.querySelectorAll('.facility-form')].map(row=>{const value=name=>row.querySelector('[name="'+name+'"]').value;return {id:row.dataset.id,name:value('facility_name'),amount:num(value('facility_amount')),currency:'NZD',type:value('facility_type'),drawAtClose:num(value('facility_draw')),termMonths:num(value('facility_term')),purposes:split(value('facility_purposes')),security:split(value('facility_security')),requiredDate:value('facility_date')||null};});if(!p.facilities.length)throw new Error('Keep at least one requested facility.');await act('profile',{profile:p});}
 if(kind==='package'){const options={pinned:[],excluded:[],locks:{}};for(const p of detail.providers){const pref=data['pref:'+p.id];if(pref==='pin')options.pinned.push(p.id);if(pref==='exclude'||data.mode==='club'&&p.mandate.data.coLend===false)options.excluded.push(p.id);if(data['lock:'+p.id])options.locks[p.id+':'+data['facility:'+p.id]]=Number(data['lock:'+p.id]);}await act('package',{name:data.name,run_id:recentRun(true)?.id,options});}
 if(kind==='choose-terms')await act('choose-terms',{record_id:form.dataset.id,reason:data.reason});
 if(kind==='choose-package')await act('choose-package',{package_id:form.dataset.id,alternative:Number(form.dataset.alternative),reason:data.reason});
 if(kind==='funding'){await act('funding',{match_id:data.match_id,facility_id:data.facility_id,kind:data.kind,state:data.state,amount:num(data.amount),expires_at:iso(data.expires_at),supersedes_id:data.supersedes_id||null,data:{...Object.fromEntries(['source','rate','benchmark','margin','received_date','term','repayment','security','floors','fees','conditions'].map(k=>[k,data[k]||null]))}});}
 if(kind==='task'){const t=detail.tasks.find(t=>t.id===form.dataset.id);await act('task',{...data,id:t?.id,task_version:t?.version,due_at:iso(data.due_at),completed:f.has('completed')});}
 if(kind==='mandate'){const p=appData.providers.find(p=>p.id===form.dataset.id),m={...p.mandate.data};for(const k of ['participationMin','participationMax','availableCapital'])m[k]=num(data[k]);Object.assign(m,{source:data.source,capacityAsAt:iso(data.capacityAsAt),coLend:data.coLend==='unknown'?null:data.coLend==='true',securityGroup:data.securityGroup||null});await api('/providers/'+encodeURIComponent(p.id)+'/mandates',{id:crypto.randomUUID(),effective_from:iso(data.effective_from),data:m});}
 await refresh('Saved');
 }catch(e){if(error&&error.isConnected)error.textContent=e.message;else notify(e.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('change',async event=>{const target=event.target;if(target.name==='template'){const p=target.value==='thirty'?appData.deals.find(d=>d.id==='DEAL-30M')?.profile:target.value==='kowhai'?appData.deals.find(d=>d.id==='DEAL-KOWHAI-001')?.profile:blankProfile();$('#intake-fields').innerHTML=profileFields(p||blankProfile());return;}if(!target.dataset.status)return;const m=detail.deal_matches.find(m=>m.id===target.dataset.status),status=target.value;if(status==='DECLINED'){target.value=m.status;const details=document.getElementById('provider-'+m.id);details.open=true;const form=details.querySelector('form');form.elements.status.value='DECLINED';form.elements.decline_reason.focus();notify('Optional: choose a reason, then Save provider activity. Leave it blank to save without a reason.');return;}target.disabled=true;try{await act('provider',{match_id:m.id,match_version:m.version,status});await refresh('Provider status saved');}catch(e){target.value=m.status;notify(e.message);}finally{target.disabled=false;}});
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;const action=b.dataset.action;if(action==='theme'){document.body.classList.toggle('dark');try{localStorage.setItem('mandate-workspace-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}b.textContent=document.body.classList.contains('dark')?'Light mode':'Dark mode';return;}if(action==='print'){window.print();return;}if(b.hasAttribute('data-remove-facility')){b.closest('.facility-form').remove();return;}if(action==='add-facility'){const rows=$('#facility-rows');if(rows.children.length>=6){notify('This demonstration supports up to six distinct facilities.');return;}rows.insertAdjacentHTML('beforeend',facilityForm({id:crypto.randomUUID(),name:'Additional facility',type:'term_loan',currency:'NZD'}));return;}if(!action&&!b.dataset.resolve&&!b.dataset.report&&!b.dataset.internalReport&&!b.dataset.preferTerms)return;b.disabled=true;try{
 if(action==='logout'){await api('/logout',{});await loginView();return;}
 if(action==='reload'){await route();return;}
 if(action==='confirm'){await act('confirm');await refresh('Profile confirmed');}
 if(action==='analyze'){await act('analyze');location.hash=dealLink(detail.deal.id,'matches');await refresh('Comparison completed');}
 if(action==='save-matches'){await act('save-matches',{run_id:recentRun().id});await refresh('Matches saved to this deal');}
 if(b.dataset.resolve){await act('resolve',{field:b.dataset.resolve,document_id:b.dataset.document||null,row:b.dataset.row?Number(b.dataset.row):null});await refresh('Source value confirmed');}
 if(b.dataset.report||b.dataset.internalReport){const r=await act('report',{result_id:b.dataset.report||b.dataset.internalReport,audience:b.dataset.internalReport?'internal':'shareable'});location.hash='#report/'+r.id;}

 }catch(e){notify(e.message);}finally{b.disabled=false;}});
window.addEventListener('hashchange',route);
route();
